    -- the row's own source time: LOAD_DATETIME for hubs, links and single-active satellites
    m.REC_REFRESH_AT,
    -- multi-active satellites on RISK_OBJECT_BK (SAT_MOTOR_AUG_RISK_MOTOR_DRIVER, SAT_MOTOR_AUG_RISK_MOTOR_EV_BATTERY, SAT_MOTOR_AUG_RISK_MOTOR_GEOGRAPHICAL_EXTENSION, SAT_RISK_MOTOR_ADDON, SAT_RISK_MOTOR_DRIVER, SAT_RISK_TRAILER):
