_CHASSIS_NUMBER, m.RISK_TRAILER__TRAILER_IDV, m.RISK_TRAILER__TRAILER_REGISTRATION_NUMBER, m.RISK_TRAILER__TRAILER_SUM_INSURED) is not null
             then m.REC_REFRESH_AT end)
        over (partition by m.RISK_OBJECT_BK) as RISK_OBJECT_BK__MA_LOAD_DATETIME
